// work.action.create — E5 AC1 / SOP-DEL-03: every action gets an owner and a date. Generated by
// `pnpm gen:command`; guard cases kept, acceptance cases added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { aStaffActor, countRows } from '@ocs/testing';
import { Forbidden, NotFound, ValidationFailed } from '../../kernel/index.ts';
import { createAction } from '../commands/create-action.ts';
import { openWorkWorld, type WorkWorld } from './fixture.ts';

const pm = aStaffActor({ roles: ['pm'] });
const other = aStaffActor({ roles: ['finance'] });
let w: WorkWorld;
const audited = async () => countRows(w.testDb.url, 'audit_event WHERE command = $1', [createAction.name]);
const input = (more: Record<string, unknown> = {}) => ({
  siteId: w.siteId,
  title: 'Send the fibre spec',
  owner: { userId: pm.id },
  due: '2026-11-13',
  source: { kind: 'visit', ref: 'Action Record 2026-11-02' },
  ...more,
});

beforeAll(async () => {
  w = await openWorkWorld();
  w.t.grant(pm, createAction.permission);
});

afterAll(async () => {
  await w.close();
});

describe('work.action.create', () => {
  it('refuses an actor without the permission and records nothing', async () => {
    await expect(w.t.kernel.execute(createAction, other, input(), 'test')).rejects.toBeInstanceOf(Forbidden);
    expect(await audited()).toBe(0);
  });

  it('refuses an action without an owner, a due date or a title (SOP-DEL-03)', async () => {
    for (const bad of [{ owner: undefined }, { due: undefined }, { title: '  ' }, { owner: { name: '' } }]) {
      await expect(w.t.kernel.execute(createAction, pm, input(bad), 'test')).rejects.toBeInstanceOf(
        ValidationFailed,
      );
    }
  });

  it('refuses a project that does not exist', async () => {
    await expect(
      w.t.kernel.execute(createAction, pm, input({ siteId: randomUUID() }), 'test'),
    ).rejects.toBeInstanceOf(NotFound);
  });

  it('creates an action owned by a user, or by a named person outside OCS, each audited once', async () => {
    const mine = await w.t.kernel.execute(createAction, pm, input(), 'test');
    const theirs = await w.t.kernel.execute(
      createAction,
      pm,
      input({ title: 'Provide the floor plan', owner: { name: 'Person A (client IT)' } }),
      'test',
    );
    expect(
      await countRows(w.testDb.url, `action WHERE id = $1 AND owner_id = $2 AND client_id IS NOT NULL`, [
        mine.id,
        pm.id,
      ]),
    ).toBe(1);
    expect(
      await countRows(w.testDb.url, `action WHERE id = $1 AND owner_name = 'Person A (client IT)'`, [
        theirs.id,
      ]),
    ).toBe(1);
    expect(await audited()).toBe(2);
  });
});
